Here's the result of running `cat -n` on a snippet of app/Http/Controllers/Admin/ScheduleDashboardController.php
     1→<?php
     2→
     3→namespace App\Http\Controllers\Admin;
     4→
     5→use App\Http\Controllers\Controller;
     6→use App\Models\Schedule;
     7→use App\Models\SchoolClass;
     8→use Illuminate\Http\Request;
     9→use Carbon\Carbon;
    10→
    11→class ScheduleDashboardController extends Controller
    12→{
    13→    public function index(Request $request)
    14→    {
    15→        $date = $request->date ? Carbon::parse($request->date) : Carbon::today();
    16→
    17→        $schedules = Schedule::with([
    18→                'mataPelajaran',
    19→                'guru',
    20→                'kelas.siswa', 'kelas.guru',
    21→                'paket.siswa', 'paket.guru', 'paket.mataPelajaran',
    22→                'absensi',
    23→            ])
    24→            ->whereDate('tanggal', $date)
    25→            ->orderBy('jam_mulai')
    26→            ->get()
    27→            ->map(function ($s) {
    28→                $now   = now();
    29→                $start = Carbon::parse($s->tanggal->format('Y-m-d') . ' ' . $s->jam_mulai);
    30→                $end   = Carbon::parse($s->tanggal->format('Y-m-d') . ' ' . $s->jam_selesai);
    31→
    32→                if ($s->status === 'selesai') {
    33→                    $displayStatus = 'completed';
    34→                } elseif ($now->between($start, $end)) {
    35→                    $displayStatus = 'ongoing';
    36→                } elseif ($now->lt($start)) {
    37→                    $displayStatus = 'scheduled';
    38→                } else {
    39→                    $displayStatus = 'completed';
    40→                }
    41→
    42→                // Student count: prefer kelas (class_students pivot), fall back to package enrollment
    43→                if ($s->kelas) {
    44→                    $studentCount = $s->kelas->siswa->count();
    45→                    $capacity     = $s->kelas->kapasitas ?? $studentCount;
    46→                } elseif ($s->paket) {
    47→                    $studentCount = $s->paket->siswa->count();
    48→                    $capacity     = $studentCount;
    49→                } else {
    50→                    $studentCount = 0;
    51→                    $capacity     = 0;
    52→                }
    53→
    54→                // Display info:
    55→                // - class_name : kelas name if linked, else paket name
    56→                // - teacher_name: schedule's own guru_id FIRST, then paket guru
    57→                // - subject_name: schedule's own mata_pelajaran_id FIRST (the specific subject for this session)
    58→                $className   = $s->kelas?->nama_kelas ?? ($s->paket?->nama ?? '—');
    59→                $teacherName = $s->guru?->name ?? ($s->paket?->guru?->name ?? '—');
    60→                $subjectName = $s->mataPelajaran?->nama
    61→                    ?? ($s->paket?->mataPelajaran?->first()?->nama ?? '—');
    62→
    63→                return [
    64→                    'id'             => $s->id,
    65→                    'class_name'     => $className,
    66→                    'teacher_name'   => $teacherName,
    67→                    'subject_name'   => $subjectName,
    68→                    'room_name'      => $s->ruangan ?? ($s->jenis === 'online' ? 'Online' : 'Offline'),
    69→                    'jam_mulai'      => $s->jam_mulai,
    70→                    'jam_selesai'    => $s->jam_selesai,
    71→                    'jenis'          => $s->jenis,
    72→                    'status'         => $displayStatus,
    73→                    'topik'          => $s->topik ?? '—',
    74→                    'students_count' => $studentCount . '/' . $capacity,
    75→                    'pertemuan_ke'   => $s->pertemuan_ke,
    76→                    'schedule_id'    => $s->id,
    77→                ];
    78→            });
    79→
    80→        $stats = [
    81→            'total'      => $schedules->count(),
    82→            'ongoing'    => $schedules->where('status', 'ongoing')->count(),
    83→            'scheduled'  => $schedules->where('status', 'scheduled')->count(),
    84→            'completed'  => $schedules->where('status', 'completed')->count(),
    85→        ];
    86→
    87→        $weekDays = [];
    88→        $weekStart = $date->copy()->startOfWeek(Carbon::MONDAY);
    89→        for ($i = 0; $i < 6; $i++) {
    90→            $d = $weekStart->copy()->addDays($i);
    91→            $weekDays[] = [
    92→                'date'    => $d->format('Y-m-d'),
    93→                'day'     => $d->isoFormat('ddd'),
    94→                'num'     => $d->format('d'),
    95→                'active'  => $d->isSameDay($date),
    96→                'count'   => Schedule::whereDate('tanggal', $d)->count(),
    97→            ];
    98→        }
    99→
   100→        $classes  = SchoolClass::with(['guru', 'mataPelajaran'])->where('status', 'aktif')->orderBy('nama_kelas')->get();
   101→
   102→        return view('admin.schedule-dashboard.index', compact(
   103→            'schedules', 'stats', 'date', 'weekDays', 'classes'
   104→        ));
   105→    }
   106→}
