Here's the result of running `cat -n` on a snippet of app/Http/Controllers/Admin/ScheduleListController.php
     1→<?php
     2→
     3→namespace App\Http\Controllers\Admin;
     4→
     5→use App\Http\Controllers\Controller;
     6→use App\Models\SchoolClass;
     7→use App\Models\Course;
     8→use Illuminate\Http\Request;
     9→
    10→class ScheduleListController extends Controller
    11→{
    12→    public function index(Request $request)
    13→    {
    14→        $branchId = auth()->user()?->admin?->branch_id;
    15→
    16→        $query = SchoolClass::with([
    17→            'guru',
    18→            'mataPelajaran',
    19→            'siswa',
    20→            'jadwal.paket',
    21→            'cabang',
    22→        ])->withCount('siswa');
    23→
    24→        if ($branchId) {
    25→            $query->where('cabang_id', $branchId);
    26→        }
    27→
    28→        if ($search = $request->search) {
    29→            $query->where(function ($q) use ($search) {
    30→                $q->where('nama_kelas', 'like', "%$search%")
    31→                  ->orWhereHas('guru', fn ($g) => $g->where('name', 'like', "%$search%"))
    32→                  ->orWhereHas('mataPelajaran', fn ($m) => $m->where('nama', 'like', "%$search%"));
    33→            });
    34→        }
    35→
    36→        if ($statusFilter = $request->status_filter) {
    37→            if ($statusFilter === 'aktif') {
    38→                $query->where('status', '!=', 'draft')
    39→                      ->whereRaw('(SELECT COUNT(*) FROM class_students WHERE class_id = school_classes.id) < COALESCE(kapasitas, 99999)');
    40→            } elseif ($statusFilter === 'penuh') {
    41→                $query->whereRaw('kapasitas > 0')
    42→                      ->whereRaw('(SELECT COUNT(*) FROM class_students WHERE class_id = school_classes.id) >= kapasitas');
    43→            } elseif ($statusFilter === 'draft') {
    44→                $query->where('status', 'draft');
    45→            }
    46→        }
    47→
    48→        if ($mapelId = $request->mata_pelajaran_id) {
    49→            $query->where('mata_pelajaran_id', $mapelId);
    50→        }
    51→
    52→        $classes = $query->orderBy('nama_kelas')->paginate(15)->withQueryString();
    53→
    54→        $dayNames = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'];
    55→
    56→        $classes->getCollection()->transform(function ($kelas) use ($dayNames) {
    57→            $enrolled = $kelas->siswa_count;
    58→            $capacity = $kelas->kapasitas ?: 0;
    59→            $pct      = $capacity > 0 ? round($enrolled / $capacity * 100) : 0;
    60→
    61→            $done  = $kelas->jadwal->where('status', 'selesai')->count();
    62→            $total = $kelas->jumlah_pertemuan ?: $kelas->jadwal->count();
    63→
    64→            $firstJadwal = $kelas->jadwal->first();
    65→            $paket       = $firstJadwal?->paket;
    66→
    67→            $room = null;
    68→            foreach ($kelas->jadwal as $j) {
    69→                if ($j->ruangan) { $room = $j->ruangan; break; }
    70→                if (!empty($j->link_meeting)) { $room = 'Link Meeting'; break; }
    71→            }
    72→            if (!$room) {
    73→                $room = in_array($kelas->jenis, ['online']) ? 'Link Meeting'
    74→                    : ($kelas->link_zoom ? 'Link Meeting' : '—');
    75→            }
    76→
    77→            $days = $kelas->jadwal
    78→                ->map(fn ($j) => optional($j->tanggal)->dayOfWeekIso)
    79→                ->filter()
    80→                ->unique()
    81→                ->sort()
    82→                ->values();
    83→            $daysStr = $days->map(fn ($d) => $dayNames[$d - 1] ?? '')->filter()->join(', ');
    84→
    85→            $timeSchedule = $kelas->jadwal->first(fn ($j) => $j->jam_mulai);
    86→            $timeStr = $timeSchedule
    87→                ? substr($timeSchedule->jam_mulai, 0, 5) . ' – ' . substr($timeSchedule->jam_selesai, 0, 5)
    88→                : '—';
    89→
    90→            $computedStatus = match (true) {
    91→                $kelas->status === 'draft'              => 'draft',
    92→                $capacity > 0 && $enrolled >= $capacity => 'penuh',
    93→                default                                  => 'aktif',
    94→            };
    95→
    96→            $jenisLabel = match ($kelas->jenis) {
    97→                'online'     => 'Online',
    98→                'home_visit' => 'Home Visit',
    99→                default      => 'In-Class',
   100→            };
   101→
   102→            $jenisColor = match ($kelas->jenis) {
   103→                'online'     => 'var(--soft-info-bg);color:var(--soft-info-text)',
   104→                'home_visit' => 'var(--soft-warning-bg);color:var(--soft-warning-text)',
   105→                default      => 'var(--soft-primary-bg);color:var(--soft-primary-text)',
   106→            };
   107→
   108→            $subjectName = $kelas->mataPelajaran?->nama ?? $kelas->nama_kelas;
   109→            $initials    = strtoupper(mb_substr(preg_replace('/[^A-Za-z]/', '', $subjectName), 0, 2));
   110→            if (strlen($initials) < 2) {
   111→                $initials = strtoupper(mb_substr($kelas->nama_kelas, 0, 2));
   112→            }
   113→
   114→            $teacherName     = $kelas->guru?->name ?? '—';
   115→            $tParts          = preg_split('/\s+/', trim($teacherName));
   116→            $teacherInitials = strtoupper(
   117→                ($tParts[0][0] ?? '') . ($tParts[1][0] ?? ($tParts[0][1] ?? ''))
   118→            );
   119→
   120→            $code = strtoupper(preg_replace('/[^A-Z0-9]/i', '', mb_substr($kelas->nama_kelas, 0, 6)))
   121→                . '-' . str_pad($kelas->id, 2, '0', STR_PAD_LEFT);
   122→
   123→            $kelas->_enrolled         = $enrolled;
   124→            $kelas->_capacity         = $capacity;
   125→            $kelas->_pct              = $pct;
   126→            $kelas->_done             = $done;
   127→            $kelas->_total            = $total;
   128→            $kelas->_paket            = $paket;
   129→            $kelas->_room             = $room;
   130→            $kelas->_days             = $daysStr;
   131→            $kelas->_time             = $timeStr;
   132→            $kelas->_computed_status  = $computedStatus;
   133→            $kelas->_jenis_label      = $jenisLabel;
   134→            $kelas->_jenis_color      = $jenisColor;
   135→            $kelas->_initials         = $initials;
   136→            $kelas->_teacher_initials = $teacherInitials;
   137→            $kelas->_code             = $code;
   138→            $kelas->_teacher_name     = $teacherName;
   139→
   140→            return $kelas;
   141→        });
   142→
   143→        $allQuery = SchoolClass::withCount('siswa');
   144→        if ($branchId) {
   145→            $allQuery->where('cabang_id', $branchId);
   146→        }
   147→        $allClasses = $allQuery->get();
   148→
   149→        $stats = [
   150→            'total'       => $allClasses->count(),
   151→            'aktif'       => $allClasses->filter(fn ($k) => $k->status !== 'draft' && ($k->kapasitas <= 0 || $k->siswa_count < $k->kapasitas))->count(),
   152→            'penuh'       => $allClasses->filter(fn ($k) => $k->kapasitas > 0 && $k->siswa_count >= $k->kapasitas)->count(),
   153→            'total_murid' => $allClasses->sum('siswa_count'),
   154→        ];
   155→
   156→        $courses = Course::orderBy('nama')->get();
   157→
   158→        return view('admin.schedule-list.index', compact('classes', 'stats', 'courses'));
   159→    }
   160→}
