     3→namespace App\Http\Controllers\Siswa;
     4→
     5→use App\Http\Controllers\Controller;
     6→use App\Models\Branch;
     7→use App\Models\Course;
     8→use App\Models\Package;
     9→use App\Models\Schedule;
    10→use App\Models\Student;
    11→use App\Models\StudentRegistration;
    12→use App\Models\Teacher;
    13→use App\Services\ScheduleAgreementService;
    14→use App\Services\ScheduleLockService;
    15→use Illuminate\Http\Request;
    16→use Illuminate\Support\Facades\DB;
    17→
    18→class CourseController extends Controller
    19→{
    20→    public function index()
    21→    {
    22→        $student = Student::where('user_id', auth()->id())->first();
    23→        if (! $student) {
    24→            return redirect()->route('dashboard')->with('error', 'Profil siswa belum lengkap.');
    25→        }
    26→
    27→        $packages = collect();
    28→
    29→        if ($student->package_id) {
    30→            $packages = $student->package()
    31→                ->with(['cabang', 'mataPelajaran'])
    32→                ->get();
    33→        }
    34→
    35→        // Load courses from approved/active registrations
    36→        $registrationCourses = collect();
    37→        $registration = StudentRegistration::where('student_id', $student->id)
    38→            ->whereIn('academic_status', ['menunggu_kelas', 'terjadwal'])
    39→            ->latest()
    40→            ->first();
    41→
    42→        if ($registration && !empty($registration->interests)) {
    43→            $registrationCourses = Course::whereIn('nama', $registration->interests)->get();
    44→        }
    45→
    46→        return view('siswa.courses.index', compact('packages', 'student', 'registrationCourses', 'registration'));
    47→    }
    48→
    49→    public function fees(Request $request)
    50→    {
    51→        $student = Student::where('user_id', auth()->id())->first();
    52→        if (! $student) {
    53→            return redirect()->route('dashboard')->with('error', 'Profil siswa belum lengkap.');
    54→        }
    55→
    56→        $packagesQuery = Package::with(['cabang', 'guru', 'mataPelajaran'])
    57→            ->where('status', 'aktif')
    58→            ->where(function ($q) use ($student) {
    59→                $q->whereNull('cabang_id')
    60→                  ->orWhere('cabang_id', $student->branch_id);
    61→            });
    62→
    63→        if ($request->filled('course_id')) {
    64→            $packagesQuery->whereHas('mataPelajaran', function ($q) use ($request) {
    65→                $q->where('courses.id', $request->course_id);
    66→            });
    67→        }
    68→        if ($request->filled('jenis')) {
    69→            $packagesQuery->where('jenis', $request->jenis);
    70→        }
    71→        if ($request->filled('guru_id')) {
    72→            $packagesQuery->where('guru_id', $request->guru_id);
    73→        }
    74→        if ($request->filled('cabang_id')) {
    75→            $packagesQuery->where('cabang_id', $request->cabang_id);
    76→        }
    77→        if ($request->filled('harga_min')) {
    78→            $packagesQuery->where('harga', '>=', $request->harga_min);
    79→        }
    80→        if ($request->filled('harga_max')) {
    81→            $packagesQuery->where('harga', '<=', $request->harga_max);
    82→        }
    83→
    84→        $packages = $packagesQuery->orderBy('nama')->get();
    85→
    86→        $courses = Course::where('status', 'aktif')
    87→            ->where(function ($q) use ($student) {
    88→                $q->whereNull('cabang_id')->orWhere('cabang_id', $student->branch_id);
    89→            })
    90→            ->orderBy('nama')
    91→            ->get();
    92→
    93→        $teachers = Teacher::where('status', 'aktif')
    94→            ->where(function ($q) use ($student) {
    95→                $q->whereNull('branch_id')->orWhere('branch_id', $student->branch_id);
    96→            })
    97→            ->orderBy('name')
    98→            ->get();
    99→
   100→        $branches = Branch::where('status', 'active')->orderBy('name')->get();
   101→
   102→        return view('siswa.courses.fees', compact('packages', 'student', 'courses', 'teachers', 'branches'));
   103→    }
   104→}
